// Synthetic replica of react-native-maps sources: TSX shipped as the
// "react-native" entry, registering native host components for the map view
// (AIRMap) and markers (AIRMapMarker) off the React Native default export.
import ReactNative from "react-native";

const requireNativeComponent =
  (ReactNative as { requireNativeComponent?: (name: string) => unknown }).requireNativeComponent ??
  ((name: string) => name);

const MapNativeComponent = requireNativeComponent("AIRMap");
const MarkerNativeComponent = requireNativeComponent("AIRMapMarker");

export const MAPS_OK = "MAPS_OK";

export type Region = {
  latitude: number;
  longitude: number;
  latitudeDelta: number;
  longitudeDelta: number;
};

export function MapView(props: { region?: Region; children?: unknown }) {
  return <MapNativeComponent region={props.region}>{props.children}</MapNativeComponent>;
}

export function Marker(props: { coordinate: { latitude: number; longitude: number } }) {
  return <MarkerNativeComponent coordinate={props.coordinate} />;
}

export default MapView;
